#include "ENGINE/Source/Tempest/cmath.h"
#include <algorithm>
#include <cmath>
namespace NTempest {
int CMath::sqrt_(unsigned v){return static_cast<int>(std::sqrt(static_cast<double>(v)));}long double __fastcall CMath::sqrt_(float v){return std::sqrt(static_cast<long double>(v));}double CMath::atanoid_(float x,float p){return std::atan(x)/p;}double CMath::logoid_(double x,double a,double b,double c,double d){return a+b*std::log(c*x+d);}double CMath::logoid2_(double x,double a,double b,double c,double d){return a+b*std::log2(c*x+d);}double CMath::logoid10_(double x,double a,double b,double c,double d){return a+b*std::log10(c*x+d);}double CMath::log2_(double x){return std::log2(x);}double CMath::exp2_(double x){return std::exp2(x);}
bool CMath::solvequad_(double&r0,double&r1,double a,double b,double c){double d=b*b-4*a*c;if(d<0||a==0)return false;d=std::sqrt(d);r0=(-b-d)/(2*a);r1=(-b+d)/(2*a);return true;}bool CMath::solvequad_(float&r0,float&r1,float a,float b,float c){double x,y;if(!solvequad_(x,y,a,b,c))return false;r0=float(x);r1=float(y);return true;}bool CMath::xsectunitsphere_(double x,double y,double z,double dx,double dy,double dz,double&t0,double&t1){return solvequad_(t0,t1,dx*dx+dy*dy+dz*dz,2*(x*dx+y*dy+z*dz),x*x+y*y+z*z-1);}
void CMath::invertarray_(float*a,unsigned n){for(unsigned i=0;i<n;++i)a[i]=1/a[i];}void CMath::sqrtarray_(double*a,unsigned n){for(unsigned i=0;i<n;++i)a[i]=std::sqrt(a[i]);}void CMath::sqrtinvarray_(double*a,unsigned n){for(unsigned i=0;i<n;++i)a[i]=1/std::sqrt(a[i]);}double CMath::spline_(unsigned n,const double*a,double x){if(!n)return 0;unsigned i=std::min<unsigned>(unsigned(std::max(0.0,x)),n-1);return a[i];}float CMath::spline_(unsigned n,const float*a,float x){if(!n)return 0;unsigned i=std::min<unsigned>(unsigned(std::max(0.0F,x)),n-1);return a[i];}
}
